import * as t from '@babel/types';
import type { ObfuscationConfig, RuntimeNames } from '../types.js';

/**
 * Builds the runtime prelude injected at the top of an obfuscated program,
 * entirely with Babel AST builders (no string templates, so no placeholder
 * collisions with ordinary identifiers like `length` or `i`):
 *
 *   1. string pool + decoder (with optional self-rotation loop)
 *   2. global tamper/degrade guard carrying the FNV-1a hash routine
 *   3. anti-debug probe (debugger timing trap + optional re-arm interval)
 *
 * Identifiers are generated by the caller and reserved in the NameGenerator,
 * so the rename pass never touches them.
 */

const id = (name: string): t.Identifier => t.identifier(name);

/** var name = init; */
function varDecl(name: string, init: t.Expression): t.VariableDeclaration {
  return t.variableDeclaration('var', [t.variableDeclarator(id(name), init)]);
}

/** Build the alphabet-inversion lookup: (function(alphabet){...})(ALPHABET) */
function buildLookupExpr(alphabet: string): t.CallExpression {
  const alphabetId = id('alphabet');
  const m = id('m');
  const i = id('i');
  return t.callExpression(
    t.functionExpression(null, [alphabetId], t.blockStatement([
      t.variableDeclaration('var', [t.variableDeclarator(m, t.objectExpression([]))]),
      t.forStatement(
        t.variableDeclaration('var', [t.variableDeclarator(i, t.numericLiteral(0))]),
        t.binaryExpression('<', i, t.memberExpression(alphabetId, id('length'))),
        t.updateExpression('++', i),
        t.expressionStatement(t.assignmentExpression(
          '=',
          t.memberExpression(m, t.memberExpression(alphabetId, i, true), true),
          i
        ))
      ),
      t.returnStatement(m),
    ])),
    [t.stringLiteral(alphabet)]
  );
}

function decoderStatements(names: RuntimeNames, cfg: ObfuscationConfig, pool: string[], alphabet: string, rotation: number): t.Statement[] {
  const useRc4 = cfg.stringEncryption.algorithm === 'rc4';
  const poolId = id(names.pool);
  const decId = id(names.decoder);
  const index = id('index');
  const key = id('key');

  // locals
  const lookup = id('lookup');
  const token = id('token');
  const clean = id('clean');
  const bytes = id('bytes');
  const i = id('i');
  const c0 = id('c0'), c1 = id('c1'), c2 = id('c2'), c3 = id('c3');
  const kb = id('kb');
  const out = id('out');
  const j = id('j'), k = id('k');
  const cache = id('__cache');

  // Memoization: hot call sites decode the same indices repeatedly. Caching the
  // decoded plaintext turns every call after the first into an object lookup,
  // which is what keeps string encryption from dominating runtime cost.
  const cacheGuard = t.ifStatement(
    t.binaryExpression('!==',
      t.memberExpression(cache, index, true),
      t.identifier('undefined')),
    t.blockStatement([t.returnStatement(t.memberExpression(cache, index, true))])
  );

  const body: t.Statement[] = [
    cacheGuard,
    varDecl('lookup', buildLookupExpr(alphabet)),
    t.variableDeclaration('var', [
      t.variableDeclarator(token, t.memberExpression(poolId, index, true)),
    ]),
    varDecl('clean', t.callExpression(t.memberExpression(token, id('replace')), [
      t.regExpLiteral('=+$', ''),
      t.stringLiteral(''),
    ])),
    varDecl('bytes', t.arrayExpression([])),
    t.variableDeclaration('var', [
      t.variableDeclarator(i), t.variableDeclarator(c0), t.variableDeclarator(c1),
      t.variableDeclarator(c2), t.variableDeclarator(c3),
    ]),
  ];

  // base64 decode loop — mirrors build-side b64decode, including partial final
  // groups (clean length % 4 can be 2 or 3 once '=' padding is stripped).
  const charAt = (n: t.Expression) => t.callExpression(t.memberExpression(clean, id('charAt')), [n]);
  const defined = (node: t.Expression) => t.binaryExpression('!==', node, t.identifier('undefined'));
  const decodeLoop = t.forStatement(
    t.assignmentExpression('=', i, t.numericLiteral(0)),
    t.binaryExpression('<', i, t.memberExpression(clean, id('length'))),
    t.assignmentExpression('+=', i, t.numericLiteral(4)),
    t.blockStatement([
      t.expressionStatement(t.assignmentExpression('=', c0, t.memberExpression(lookup, charAt(i), true))),
      t.expressionStatement(t.assignmentExpression('=', c1,
        t.memberExpression(lookup, charAt(t.binaryExpression('+', i, t.numericLiteral(1))), true))),
      t.expressionStatement(t.assignmentExpression('=', c2,
        t.memberExpression(lookup, charAt(t.binaryExpression('+', i, t.numericLiteral(2))), true))),
      t.expressionStatement(t.assignmentExpression('=', c3,
        t.memberExpression(lookup, charAt(t.binaryExpression('+', i, t.numericLiteral(3))), true))),
      // first byte always present (a valid group has at least 2 chars)
      t.expressionStatement(t.callExpression(t.memberExpression(bytes, id('push')), [
        t.binaryExpression('|', t.binaryExpression('<<', c0, t.numericLiteral(2)),
          t.binaryExpression('>>', c1, t.numericLiteral(4))),
      ])),
      t.ifStatement(
        defined(c2),
        t.blockStatement([t.expressionStatement(t.callExpression(t.memberExpression(bytes, id('push')), [
          t.binaryExpression('|',
            t.binaryExpression('<<', t.binaryExpression('&', c1, t.numericLiteral(15)), t.numericLiteral(4)),
            t.binaryExpression('>>', c2, t.numericLiteral(2))),
        ]))])
      ),
      t.ifStatement(
        defined(c3),
        t.blockStatement([t.expressionStatement(t.callExpression(t.memberExpression(bytes, id('push')), [
          t.binaryExpression('|',
            t.binaryExpression('<<', t.binaryExpression('&', c2, t.numericLiteral(3)), t.numericLiteral(6)),
            c3),
        ]))])
      ),
    ])
  );
  body.push(decodeLoop);

  // key bytes
  body.push(varDecl('kb', t.arrayExpression([
    t.binaryExpression('&', t.binaryExpression('>>>', key, t.numericLiteral(24)), t.numericLiteral(255)),
    t.binaryExpression('&', t.binaryExpression('>>>', key, t.numericLiteral(16)), t.numericLiteral(255)),
    t.binaryExpression('&', t.binaryExpression('>>>', key, t.numericLiteral(8)), t.numericLiteral(255)),
    t.binaryExpression('&', key, t.numericLiteral(255)),
  ])));
  body.push(varDecl('out', t.arrayExpression([])));
  body.push(t.variableDeclaration('var', [
    t.variableDeclarator(j), t.variableDeclarator(k),
    ...(useRc4 ? [t.variableDeclarator(id('tmp'))] : []),
  ]));

  if (useRc4) {
    const s = id('s');
    const tmp = id('tmp');
    body.push(varDecl('s', t.arrayExpression([])));
    // KSA
    body.push(t.forStatement(
      t.assignmentExpression('=', i, t.numericLiteral(0)),
      t.binaryExpression('<', i, t.numericLiteral(256)),
      t.updateExpression('++', i),
      t.expressionStatement(t.assignmentExpression('=', t.memberExpression(s, i, true), i))
    ));
    body.push(t.expressionStatement(t.assignmentExpression('=', j, t.numericLiteral(0))));
    body.push(t.forStatement(
      t.assignmentExpression('=', i, t.numericLiteral(0)),
      t.binaryExpression('<', i, t.numericLiteral(256)),
      t.updateExpression('++', i),
      t.blockStatement([
        t.expressionStatement(t.assignmentExpression('=', j,
          t.binaryExpression('&',
            t.binaryExpression('+', t.binaryExpression('+', j, t.memberExpression(s, i, true)),
              t.memberExpression(kb, t.binaryExpression('%', i, t.numericLiteral(4)), true)),
            t.numericLiteral(255)))),
        t.expressionStatement(t.assignmentExpression('=', tmp, t.memberExpression(s, i, true))),
        t.expressionStatement(t.assignmentExpression('=',
          t.memberExpression(s, i, true), t.memberExpression(s, j, true))),
        t.expressionStatement(t.assignmentExpression('=',
          t.memberExpression(s, j, true), tmp)),
      ])
    ));
    // PRGA
    body.push(t.expressionStatement(t.assignmentExpression('=', i, t.numericLiteral(0))));
    body.push(t.expressionStatement(t.assignmentExpression('=', j, t.numericLiteral(0))));
    body.push(t.forStatement(
      t.assignmentExpression('=', k, t.numericLiteral(0)),
      t.binaryExpression('<', k, t.memberExpression(bytes, id('length'))),
      t.updateExpression('++', k),
      t.blockStatement([
        t.expressionStatement(t.assignmentExpression('=', i,
          t.binaryExpression('&', t.binaryExpression('+', i, t.numericLiteral(1)), t.numericLiteral(255)))),
        t.expressionStatement(t.assignmentExpression('=', j,
          t.binaryExpression('&', t.binaryExpression('+', j, t.memberExpression(s, i, true)), t.numericLiteral(255)))),
        t.expressionStatement(t.assignmentExpression('=', tmp, t.memberExpression(s, i, true))),
        t.expressionStatement(t.assignmentExpression('=',
          t.memberExpression(s, i, true), t.memberExpression(s, j, true))),
        t.expressionStatement(t.assignmentExpression('=',
          t.memberExpression(s, j, true), tmp)),
        t.expressionStatement(t.callExpression(t.memberExpression(out, id('push')), [
          t.binaryExpression('^', t.memberExpression(bytes, k, true),
            t.memberExpression(s,
              t.binaryExpression('&',
                t.binaryExpression('+', t.memberExpression(s, i, true), t.memberExpression(s, j, true)),
                t.numericLiteral(255)),
              true)),
        ])),
      ])
    ));
  } else {
    body.push(t.forStatement(
      t.assignmentExpression('=', k, t.numericLiteral(0)),
      t.binaryExpression('<', k, t.memberExpression(bytes, id('length'))),
      t.updateExpression('++', k),
      t.expressionStatement(t.callExpression(t.memberExpression(out, id('push')), [
        t.binaryExpression('^', t.memberExpression(bytes, k, true),
          t.memberExpression(kb, t.binaryExpression('%', k, t.numericLiteral(4)), true)),
      ]))
    ));
  }

  // reassemble UTF-16, cache it, and return
  const str = id('str');
  body.push(varDecl('str', t.stringLiteral('')));
  body.push(t.forStatement(
    t.assignmentExpression('=', k, t.numericLiteral(0)),
    t.binaryExpression('<', k, t.memberExpression(out, id('length'))),
    t.assignmentExpression('+=', k, t.numericLiteral(2)),
    t.expressionStatement(t.assignmentExpression('+=', str,
      t.callExpression(t.memberExpression(t.memberExpression(id('String'), id('fromCharCode')), id('call')), [
        id('String'),
        t.binaryExpression('|',
          t.binaryExpression('<<', t.memberExpression(out, k, true), t.numericLiteral(8)),
          t.memberExpression(out, t.binaryExpression('+', k, t.numericLiteral(1)), true)),
      ])))
  ));
  body.push(t.expressionStatement(
    t.assignmentExpression('=', t.memberExpression(cache, index, true), str)));
  body.push(t.returnStatement(str));

  const stmts: t.Statement[] = [
    t.variableDeclaration('var', [t.variableDeclarator(poolId,
      t.arrayExpression(pool.map((s) => t.stringLiteral(s))))]),
    t.variableDeclaration('var', [t.variableDeclarator(cache, t.objectExpression([]))]),
    t.functionDeclaration(decId, [index, key], t.blockStatement(body)),
  ];

  // optional pool self-rotation (left rotation)
  if (cfg.stringEncryption.rotatePool && rotation > 0) {
    const r = id('r');
    stmts.push(t.expressionStatement(t.callExpression(
      t.functionExpression(null, [r], t.blockStatement([
        t.whileStatement(t.identifier('r'), t.blockStatement([
          t.expressionStatement(t.callExpression(t.memberExpression(poolId, id('push')), [
            t.callExpression(t.memberExpression(poolId, id('shift')), []),
          ])),
          t.expressionStatement(t.assignmentExpression('=', r,
            t.binaryExpression('-', r, t.numericLiteral(1)))),
        ])),
      ])),
      [t.numericLiteral(rotation)]
    )));
  }
  return stmts;
}

function guardStatements(names: RuntimeNames, violationMode: 'throw' | 'degrade'): t.Statement[] {
  const guardLocal = id(names.guardLocal);
  const guardName = t.stringLiteral(names.guardGlobal);
  const globalThisId = id('globalThis');

  // hash(input): FNV-1a over UTF-16 code units
  const hashFn = t.functionExpression(null, [id('input')], t.blockStatement([
    varDecl('h', t.numericLiteral(0x811c9dc5)),
    t.forStatement(
      varDecl('i', t.numericLiteral(0)),
      t.binaryExpression('<', id('i'), t.memberExpression(id('input'), id('length'))),
      t.updateExpression('++', id('i')),
      t.blockStatement([
        t.expressionStatement(t.assignmentExpression('^=', id('h'),
          t.callExpression(t.memberExpression(id('input'), id('charCodeAt')), [id('i')]))),
        t.expressionStatement(t.assignmentExpression('=', id('h'),
          t.binaryExpression('>>>',
            t.callExpression(t.memberExpression(id('Math'), id('imul')), [id('h'), t.numericLiteral(0x01000193)]),
            t.numericLiteral(0)))),
      ])
    ),
    t.returnStatement(t.binaryExpression('>>>', id('h'), t.numericLiteral(0))),
  ]));

  const failFn = t.functionExpression(null, [id('kind')], t.blockStatement([
    t.expressionStatement(t.assignmentExpression('=', t.memberExpression(id('this'), id('tampered')), t.booleanLiteral(true))),
    t.expressionStatement(t.assignmentExpression('=', t.memberExpression(id('this'), id('degraded')), t.booleanLiteral(true))),
    t.ifStatement(
      t.binaryExpression('===', id('kind'), t.stringLiteral('throw')),
      t.blockStatement([t.throwStatement(t.newExpression(id('Error'), [t.stringLiteral('integrity violation')]))])
    ),
  ]));

  const registerFallbackFn = t.functionExpression(null, [id('name'), id('fn')], t.blockStatement([
    t.expressionStatement(t.assignmentExpression('=',
      t.memberExpression(t.memberExpression(id('this'), id('fallbacks')), id('name'), true), id('fn'))),
  ]));

  const runFn = t.functionExpression(null, [id('name'), id('fn'), id('thisArg'), id('args')], t.blockStatement([
    t.ifStatement(
      t.memberExpression(id('this'), id('degraded')),
      t.blockStatement([
        t.ifStatement(
          t.memberExpression(t.memberExpression(id('this'), id('fallbacks')), id('name'), true),
          t.blockStatement([t.returnStatement(t.callExpression(
            t.memberExpression(t.memberExpression(t.memberExpression(id('this'), id('fallbacks')), id('name'), true), id('apply')),
            [id('thisArg'), id('args')]))])
        ),
        t.throwStatement(t.newExpression(id('Error'), [
          t.binaryExpression('+', t.stringLiteral('runtime degraded: '), id('name')),
        ])),
      ])
    ),
    t.returnStatement(t.callExpression(t.memberExpression(id('fn'), id('apply')), [id('thisArg'), id('args')])),
  ]));

  const setDegradedFn = t.functionExpression(null, [id('v')], t.blockStatement([
    t.expressionStatement(t.assignmentExpression('=',
      t.memberExpression(id('this'), id('degraded')),
      t.unaryExpression('!', t.unaryExpression('!', id('v'))))),
    t.ifStatement(id('v'), t.blockStatement([
      t.expressionStatement(t.assignmentExpression('=', t.memberExpression(id('this'), id('tampered')), t.booleanLiteral(true))),
    ])),
  ]));

  const resetFn = t.functionExpression(null, [], t.blockStatement([
    t.expressionStatement(t.assignmentExpression('=', t.memberExpression(id('this'), id('tampered')), t.booleanLiteral(false))),
    t.expressionStatement(t.assignmentExpression('=', t.memberExpression(id('this'), id('degraded')), t.booleanLiteral(false))),
  ]));

  const guardObject = t.objectExpression([
    t.objectProperty(id('tampered'), t.booleanLiteral(false)),
    t.objectProperty(id('degraded'), t.booleanLiteral(false)),
    t.objectProperty(id('fallbacks'), t.callExpression(t.memberExpression(id('Object'), id('create')), [t.nullLiteral()])),
    t.objectProperty(id('mode'), t.stringLiteral(violationMode)),
    t.objectProperty(id('hash'), hashFn),
    t.objectProperty(id('fail'), failFn),
    t.objectProperty(id('registerFallback'), registerFallbackFn),
    t.objectProperty(id('run'), runFn),
    t.objectProperty(id('setDegraded'), setDegradedFn),
    t.objectProperty(id('reset'), resetFn),
  ]);

  const globalSlot = t.memberExpression(globalThisId, guardName, true);
  return [
    t.variableDeclaration('var', [t.variableDeclarator(guardLocal,
      t.logicalExpression('||', globalSlot,
        t.assignmentExpression('=', globalSlot, guardObject)))]),
  ];
}

function antiDebugStatements(names: RuntimeNames, cfg: ObfuscationConfig): t.Statement[] {
  const probe = id(names.antiDebug);
  const guardLocal = id(names.guardLocal);
  const now = id('now');
  const start = id('start');
  const elapsed = id('elapsed');

  const nowFn = t.conditionalExpression(
    t.logicalExpression('&&',
      t.binaryExpression('!==', t.unaryExpression('typeof', id('performance')), t.stringLiteral('undefined')),
      t.memberExpression(id('performance'), id('now'))),
    t.functionExpression(null, [], t.blockStatement([
      t.returnStatement(t.callExpression(t.memberExpression(id('performance'), id('now')), [])),
    ])),
    t.functionExpression(null, [], t.blockStatement([
      t.returnStatement(t.callExpression(t.memberExpression(id('Date'), id('now')), [])),
    ]))
  );

  const stmts: t.Statement[] = [
    t.functionDeclaration(probe, [], t.blockStatement([
      varDecl('now', nowFn),
      varDecl('start', t.callExpression(now, [])),
      t.debuggerStatement(),
      varDecl('elapsed', t.binaryExpression('-', t.callExpression(now, []), start)),
      t.ifStatement(
        t.binaryExpression('>', elapsed, t.numericLiteral(cfg.antiDebug.timingThresholdMs)),
        t.blockStatement([t.expressionStatement(t.callExpression(
          t.memberExpression(guardLocal, id('setDegraded')), [t.booleanLiteral(true)]))])
      ),
      t.returnStatement(elapsed),
    ])),
    t.expressionStatement(t.callExpression(probe, [])),
    t.expressionStatement(t.assignmentExpression('=',
      t.memberExpression(guardLocal, id('probe')), probe)),
  ];

  if (cfg.antiDebug.intervalMs > 0) {
    const timer = id('_timer');
    stmts.push(t.ifStatement(
      t.binaryExpression('>', t.numericLiteral(cfg.antiDebug.intervalMs), t.numericLiteral(0)),
      t.blockStatement([
        t.variableDeclaration('var', [t.variableDeclarator(timer,
          t.callExpression(id('setInterval'), [probe, t.numericLiteral(cfg.antiDebug.intervalMs)]))]),
        t.ifStatement(
          t.binaryExpression('===', t.unaryExpression('typeof', t.memberExpression(timer, id('unref'))), t.stringLiteral('function')),
          t.blockStatement([t.expressionStatement(t.callExpression(t.memberExpression(timer, id('unref')), []))])
        ),
      ])
    ));
  }
  return stmts;
}

export function buildPrelude(
  names: RuntimeNames,
  cfg: ObfuscationConfig,
  pool: string[],
  alphabet: string,
  rotation: number
): t.Statement[] {
  const stmts: t.Statement[] = [];
  if (cfg.stringEncryption.enabled) {
    stmts.push(...decoderStatements(names, cfg, pool, alphabet, rotation));
  }
  if (cfg.integrity.enabled || cfg.antiDebug.enabled) {
    stmts.push(...guardStatements(names, cfg.integrity.onViolation));
  }
  if (cfg.antiDebug.enabled) {
    stmts.push(...antiDebugStatements(names, cfg));
  }
  return stmts;
}

/** Declaration of the opaque-predicate runtime constant used by dead-code pass. */
export function buildOpaqueConstant(names: RuntimeNames, value: number): t.Statement {
  return t.variableDeclaration('var', [
    t.variableDeclarator(id(names.opaque), t.numericLiteral(value)),
  ]);
}
